 "content": "def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    by_row = {}
    for r, c in points:
        by_row.setdefault(r, []).append(c)
    anchor_rows = [(r, cs) for r, cs in by_row.items() if len(cs) >= 2]
    if not anchor_rows:
        return out
    # The two same-row markers define the main horizontal span and branch level.
    r0, cs = max(anchor_rows, key=lambda item: len(item[1]))
    lo, hi = min(cs), max(cs)
    for c in range(lo, hi + 1):
        if out[r0][c] == 0:
            out[r0][c] = 3
    for r, c in points:
        if r != r0 and lo <= c <= hi:
            step = 1 if r > r0 else -1
            for rr in range(r0 + step, r, step):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    return out
